const UMBRAL_RAFAGA_CIERRE_KT = 45;
const UMBRAL_VIENTO_SOSTENIDO_ALERTA_KT = 30;
const UMBRAL_VISIBILIDAD_CIERRE_M = 1500;
const VENTANA_MINUTOS = 45;

const data = $json;
const clima = data.reporte_meteorologico;
const vuelos = data.vuelos_programados || [];

const hayTormentaElectrica = !!clima.actividad_electrica;
const hayWindshear = !!clima.windshear_reportado;
const rafagaKt = (clima.viento && clima.viento.rafaga_kt) || 0;
const vientoSostenidoKt = (clima.viento && clima.viento.velocidad_kt) || 0;
const visibilidadM = clima.visibilidad_m || 9999;

const condicionNivel3 =
  hayTormentaElectrica && (rafagaKt >= UMBRAL_RAFAGA_CIERRE_KT || hayWindshear);

const condicionNivel2 =
  !condicionNivel3 &&
  (hayTormentaElectrica || rafagaKt >= UMBRAL_RAFAGA_CIERRE_KT || visibilidadM <= UMBRAL_VISIBILIDAD_CIERRE_M);

const condicionNivel1 =
  !condicionNivel3 && !condicionNivel2 && vientoSostenidoKt >= UMBRAL_VIENTO_SOSTENIDO_ALERTA_KT;

let riesgoNivel = 0;
if (condicionNivel3) riesgoNivel = 3;
else if (condicionNivel2) riesgoNivel = 2;
else if (condicionNivel1) riesgoNivel = 1;

const ahora = new Date(clima.hora_reporte_utc);

const vuelosAfectados = vuelos
  .map((vuelo) => {
    const horaVuelo = new Date(vuelo.hora_programada_utc);
    const minutosHastaVuelo = Math.round((horaVuelo.getTime() - ahora.getTime()) / 60000);
    return Object.assign({}, vuelo, { minutos_hasta_operacion: minutosHastaVuelo });
  })
  .filter((vuelo) => vuelo.minutos_hasta_operacion >= 0 && vuelo.minutos_hasta_operacion <= VENTANA_MINUTOS);

const accionesPorNivel = {
  0: 'OPERACION_NORMAL',
  1: 'MONITOREO_ACTIVO',
  2: 'ALERTA_PREPARAR_CIERRE',
  3: 'CIERRE_RAMPA',
};

// Version sin guion bajo, solo para texto libre (Telegram): un \"_\" suelto se
// interpreta como inicio de cursiva en Markdown y Telegram rechaza el mensaje
// entero si no encuentra el cierre (\"can't find end of the entity\").
const accionesPorNivelLegible = {
  0: 'Operacion Normal',
  1: 'Monitoreo Activo',
  2: 'Alerta - Preparar Cierre',
  3: 'Cierre de Rampa',
};

const accionRequerida = accionesPorNivel[riesgoNivel];
const accionRequeridaLegible = accionesPorNivelLegible[riesgoNivel];

const resumen =
  `Nivel de riesgo ${riesgoNivel} (${accionRequeridaLegible}) en ${clima.estacion}. ` +
  `Viento ${vientoSostenidoKt}kt, rafagas ${rafagaKt}kt. ` +
  `Tormenta electrica: ${hayTormentaElectrica ? 'SI' : 'NO'}. ` +
  `Windshear: ${hayWindshear ? 'SI' : 'NO'}. ` +
  `${vuelosAfectados.length} vuelo(s) afectado(s) en los proximos ${VENTANA_MINUTOS} minutos.`;

return [
  {
    json: {
      riesgo_nivel: riesgoNivel,
      riesgo_nivel_3: riesgoNivel === 3,
      accion_requerida: accionRequerida,
      resumen,
      cantidad_vuelos_afectados: vuelosAfectados.length,
      vuelos_afectados: vuelosAfectados,
      reporte_meteorologico: clima,
    },
  },
];

// Nodo Code: "Construir HTML del Reporte"
// Genera el HTML (+ footer de paginacion) del reporte de incidente con
// identidad visual propia (Aeropuertos Argentina 2000) para convertirlo a PDF
// en el nodo siguiente via Gotenberg. Reemplaza al viejo "Registrar Auditoria"
// en Google Sheets: ahora el registro del incidente es este PDF.

const data = $json;
const clima = data.reporte_meteorologico || {};
const vuelos = data.vuelos_afectados || [];
const nivel = data.riesgo_nivel;

// Paleta propia (petroleo + dorado + terracota), NO colores semanticos de
// framework: los dos niveles de severidad son variaciones tonales de la MISMA
// paleta calida, no un semaforo azul/amarillo/rojo generico.
const BRAND = '#0B3B39';
const ACCENT_NIVEL2 = '#C08A2E';
const ACCENT_NIVEL2_SUAVE = '#F5EBD8';
const ACCENT_NIVEL3 = '#8C3A2E';
const ACCENT_NIVEL3_SUAVE = '#F2E2DE';

const colorNivel = nivel === 3 ? ACCENT_NIVEL3 : nivel === 2 ? ACCENT_NIVEL2 : BRAND;
const colorNivelSuave = nivel === 3 ? ACCENT_NIVEL3_SUAVE : nivel === 2 ? ACCENT_NIVEL2_SUAVE : '#EAEFEE';
const etiquetasNivel = { 2: 'Alerta - Preparar Cierre', 3: 'Cierre de Rampa' };
const etiquetaNivel = etiquetasNivel[nivel] || 'Reporte Operacional';
const generadoEl = new Date().toISOString();
const referencia = 'RPT-' + Date.now();

// Hash corto y determinista del contenido, solo para que el pie tecnico se
// sienta como el checksum de un sistema real (no es criptografico).
function hashCorto(texto) {
  let h = 5381;
  for (let i = 0; i < texto.length; i++) h = (h * 33) ^ texto.charCodeAt(i);
  return (h >>> 0).toString(16).toUpperCase().padStart(8, '0');
}
const hashReporte = hashCorto(referencia + (data.resumen || '') + generadoEl);

// Isotipo: no es un icono generico de libreria (flecha/pin) sino un motivo de
// radar de control de trafico aereo (anillos de barrido + blip), a juego con
// la paleta propia.
const svgRadar =
  '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">' +
  '<circle cx="12" cy="12" r="9.5" stroke="white" stroke-opacity="0.22" stroke-width="1"/>' +
  '<circle cx="12" cy="12" r="6.2" stroke="white" stroke-opacity="0.4" stroke-width="1"/>' +
  '<circle cx="12" cy="12" r="3" stroke="white" stroke-opacity="0.65" stroke-width="1"/>' +
  `<line x1="12" y1="12" x2="19" y2="6" stroke="${ACCENT_NIVEL2}" stroke-width="1.4" stroke-linecap="round"/>` +
  `<circle cx="12" cy="12" r="1.3" fill="${ACCENT_NIVEL2}"/>` +
  '</svg>';

const filasVuelos = vuelos.length
  ? vuelos
      .map(
        (v) => `
    <tr>
      <td class="flight">${v.vuelo || ''}</td>
      <td>${v.aerolinea || ''}</td>
      <td>${v.tipo_operacion || ''}</td>
      <td>${v.posicion_rampa || ''}</td>
      <td class="num">${v.minutos_hasta_operacion != null ? v.minutos_hasta_operacion + ' min' : '-'}</td>
    </tr>`,
      )
      .join('')
  : '<tr><td colspan="5" style="text-align:center;color:#74827D;padding:24px;">Sin vuelos afectados en la ventana evaluada</td></tr>';

const html = `<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="utf-8" />
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500&family=IBM+Plex+Sans:wght@400;500;600;700&display=swap">
<style>
  :root {
    --brand: ${BRAND};
    --ink: #16221F;
    --ink-soft: #3F4D49;
    --muted: #74827D;
    --line: #E1E6E3;
    --surface: #F6F7F5;
    --accent: ${colorNivel};
    --accent-soft: ${colorNivelSuave};
  }
  * { box-sizing: border-box; }
  html, body { margin: 0; padding: 0; }
  body {
    font-family: 'IBM Plex Sans', Georgia, 'Segoe UI', sans-serif;
    color: var(--ink);
    font-size: 13.5px;
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
    position: relative;
  }
  .watermark {
    position: fixed;
    top: 46%;
    left: 50%;
    transform: translate(-50%, -50%) rotate(-24deg);
    font-size: 64px;
    font-weight: 700;
    letter-spacing: 0.06em;
    color: var(--brand);
    opacity: 0.035;
    white-space: nowrap;
    z-index: 0;
  }
  .page { position: relative; z-index: 1; padding: 40px 48px 28px; }

  .masthead { display: flex; align-items: center; justify-content: space-between; padding-bottom: 18px; border-bottom: 1px solid var(--line); }
  .brand { display: flex; align-items: center; gap: 11px; }
  .brand-mark { width: 38px; height: 38px; border-radius: 10px; background: var(--brand); display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
  .brand-name { font-size: 11px; font-weight: 600; letter-spacing: 0.13em; text-transform: uppercase; color: var(--brand); }
  .brand-sub { font-size: 10px; color: var(--muted); letter-spacing: 0.03em; margin-top: 2px; }
  .meta { text-align: right; font-family: 'IBM Plex Mono', Consolas, monospace; font-size: 9.5px; color: var(--muted); line-height: 1.7; }

  .hero { margin-top: 40px; margin-bottom: 36px; }
  .kicker { margin: 0 0 8px; font-size: 11px; font-weight: 600; letter-spacing: 0.12em; text-transform: uppercase; color: var(--muted); }
  .hero h1 { margin: 0 0 22px; font-size: 27px; font-weight: 600; letter-spacing: -0.01em; color: var(--brand); max-width: 480px; }
  .severity-strip { display: flex; align-items: center; justify-content: space-between; padding: 14px 20px; border-radius: 10px; background: var(--accent-soft); }
  .severity-strip .label { display: flex; align-items: center; gap: 9px; font-size: 13.5px; font-weight: 600; color: var(--accent); }
  .severity-strip .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--accent); }
  .severity-strip .rule { flex: 1; height: 1px; background: var(--accent); opacity: 0.25; margin: 0 18px; }
  .severity-strip .n { font-family: 'IBM Plex Mono', Consolas, monospace; font-size: 11px; color: var(--accent); opacity: 0.85; }

  .summary { margin-top: 18px; font-size: 13px; color: var(--ink-soft); line-height: 1.65; max-width: 620px; }

  .grid { margin-top: 26px; display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
  .card { border: 1px solid var(--line); border-radius: 8px; padding: 13px 15px; }
  .card h3 { margin: 0 0 9px; font-size: 9.5px; font-weight: 600; letter-spacing: 0.1em; text-transform: uppercase; color: var(--muted); }
  .stat-row { display: flex; align-items: baseline; justify-content: space-between; padding: 3px 0; }
  .stat-label { font-size: 11.5px; color: var(--muted); }
  .stat-value { font-size: 12.5px; font-weight: 500; color: var(--ink); font-variant-numeric: tabular-nums; }
  .stat-value.lg { font-size: 16px; font-weight: 600; color: var(--brand); }

  .terminal { margin-top: 10px; border-radius: 8px; overflow: hidden; border: 1px solid #0A2A28; }
  .terminal-bar { display: flex; align-items: center; justify-content: space-between; background: #0A2A28; padding: 7px 12px; }
  .terminal-bar .dots { display: flex; gap: 4px; }
  .terminal-bar .dots span { width: 6px; height: 6px; border-radius: 50%; background: rgba(255,255,255,0.25); }
  .terminal-bar .label { font-family: 'IBM Plex Mono', Consolas, monospace; font-size: 9px; letter-spacing: 0.1em; color: rgba(255,255,255,0.5); text-transform: uppercase; }
  .terminal-body { padding: 12px 14px; background: var(--brand); color: #CFE3E0; font-family: 'IBM Plex Mono', Consolas, monospace; font-size: 10.5px; letter-spacing: 0.01em; word-break: break-all; }

  .section-label { margin: 30px 0 2px; font-size: 9.5px; font-weight: 600; letter-spacing: 0.1em; text-transform: uppercase; color: var(--muted); }
  table { width: 100%; border-collapse: collapse; margin-top: 10px; border-top: 2px solid var(--brand); }
  thead th { text-align: left; font-size: 9.5px; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; color: var(--muted); padding: 8px 10px 6px; }
  thead th:last-child { text-align: right; }
  tbody td { padding: 8px 10px; font-size: 12.5px; color: var(--ink-soft); border-bottom: 1px solid var(--surface); }
  tbody tr:last-child td { border-bottom: none; }
  td.num { text-align: right; font-variant-numeric: tabular-nums; color: var(--ink); font-weight: 500; }
  td.flight { font-weight: 600; color: var(--brand); }

  .tech-footer { margin-top: 44px; padding-top: 12px; border-top: 1px solid var(--line); display: flex; justify-content: space-between; font-family: 'IBM Plex Mono', Consolas, monospace; font-size: 9px; color: var(--muted); letter-spacing: 0.02em; }
</style>
</head>
<body>
  <div class="watermark">AA2000 &middot; OPERACIONAL</div>
  <div class="page">
    <div class="masthead">
      <div class="brand">
        <div class="brand-mark">${svgRadar}</div>
        <div>
          <div class="brand-name">Aeropuertos Argentina 2000</div>
          <div class="brand-sub">Operaciones de Rampa</div>
        </div>
      </div>
      <div class="meta">REF ${referencia}<br/>${generadoEl}</div>
    </div>

    <div class="hero">
      <p class="kicker">Protocolo de Cierre de Rampa</p>
      <h1>Reporte de Incidente Operacional</h1>
      <div class="severity-strip">
        <span class="label"><span class="dot"></span>Nivel ${nivel} &middot; ${etiquetaNivel}</span>
        <span class="rule"></span>
        <span class="n">${clima.estacion || '-'}</span>
      </div>
      <div class="summary">${data.resumen || ''}</div>
    </div>

    <div class="grid">
      <div class="card">
        <h3>Estacion</h3>
        <div class="stat-row"><span class="stat-label">Codigo</span><span class="stat-value lg">${clima.estacion || '-'}</span></div>
        <div class="stat-row"><span class="stat-label">Nombre</span><span class="stat-value">${clima.nombre_estacion || '-'}</span></div>
        <div class="stat-row"><span class="stat-label">Hora de reporte (UTC)</span><span class="stat-value">${clima.hora_reporte_utc || '-'}</span></div>
      </div>
      <div class="card">
        <h3>Condiciones de Viento</h3>
        <div class="stat-row"><span class="stat-label">Sostenido</span><span class="stat-value">${(clima.viento && clima.viento.velocidad_kt) || 0} kt</span></div>
        <div class="stat-row"><span class="stat-label">Rafaga</span><span class="stat-value">${(clima.viento && clima.viento.rafaga_kt) || 0} kt</span></div>
        <div class="stat-row"><span class="stat-label">Visibilidad</span><span class="stat-value">${clima.visibilidad_m || '-'} m</span></div>
        <div class="stat-row"><span class="stat-label">Tormenta / Windshear</span><span class="stat-value">${clima.actividad_electrica ? 'Si' : 'No'} / ${clima.windshear_reportado ? 'Si' : 'No'}</span></div>
      </div>
    </div>

    <div class="terminal">
      <div class="terminal-bar">
        <span class="label">Datos Raw &middot; METAR</span>
        <span class="dots"><span></span><span></span><span></span></span>
      </div>
      <div class="terminal-body">${clima.metar_crudo || 'METAR no disponible'}</div>
    </div>

    <p class="section-label">Vuelos Afectados (${vuelos.length})</p>
    <table>
      <thead><tr><th>Vuelo</th><th>Aerolinea</th><th>Operacion</th><th>Posicion</th><th>Ventana</th></tr></thead>
      <tbody>${filasVuelos}</tbody>
    </table>

    <div class="tech-footer">
      <span>Sistema de Triage Operacional &middot; v2.4.0</span>
      <span>SHA ${hashReporte}</span>
    </div>
  </div>
</body>
</html>`;

const footerHtml = `<!DOCTYPE html>
<html>
<head>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { width: 100%; font-family: Consolas, 'Liberation Mono', Menlo, monospace; font-size: 8px; color: #74827D; }
  table { width: 100%; border-collapse: collapse; }
  td { padding: 0 48px; white-space: nowrap; }
  td.right { text-align: right; }
</style>
</head>
<body>
  <table><tr>
    <td>SISTEMA DE TRIAGE OPERACIONAL &middot; AA2000</td>
    <td class="right"><span class="pageNumber"></span> / <span class="totalPages"></span></td>
  </tr></table>
</body>
</html>`;

const binaryHtml = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf-8'), 'index.html', 'text/html');
const binaryFooter = await this.helpers.prepareBinaryData(Buffer.from(footerHtml, 'utf-8'), 'footer.html', 'text/html');

return [{ json: data, binary: { data: binaryHtml, footer: binaryFooter } }];

// Gate de rate-limiting: no queremos golpear OpenWeatherMap/AviationStack cada
// 10 segundos (los planes gratuitos no lo soportan). El Schedule Trigger corre
// cada 10s para que el MOTOR DE TRIAGE reaccione rapido sobre datos ya conocidos,
// pero las llamadas HTTP reales solo se disparan cada `refresco_apis_min` minutos,
// usando workflow static data como cache entre ejecuciones. Se cachean los DOS
// formatos (Triage y Cierre de Rampa) para que ambos sistemas fusionados puedan
// reusar el mismo dato en vivo sin volver a llamar a las APIs externas.

const data = $getWorkflowStaticData('global');
const config = $('Configuracion (Editar Aca)').first().json;
const refrescoMs = (config.refresco_apis_min || 5) * 60000;
const ahora = Date.now();
const ultimaConsulta = data.ultimaConsultaApisTimestamp || 0;
const necesitaRefresco = (ahora - ultimaConsulta) >= refrescoMs;

return [
  {
    json: {
      necesita_refresco: necesitaRefresco,
      meteorologia_cacheada: data.meteorologiaCacheada || null,
      vuelos_activos_cacheados: data.vuelosActivosCacheados || null,
      reporte_meteorologico_cacheado: data.reporteMeteorologicoCacheado || null,
      vuelos_programados_cacheados: data.vuelosProgramadosCacheados || null,
    },
  },
];

// Capa de normalizacion (Anti-Corruption Layer): traduce las respuestas crudas
// de OpenWeatherMap y AviationStack a DOS contratos internos que comparten el
// mismo dato en vivo: el formato del motor de Triage (meteorologia + vuelos_activos)
// y el formato del motor original de Cierre de Rampa por Tormenta
// (reporte_meteorologico + vuelos_programados). Asi los dos sistemas construidos
// en este workflow quedan fusionados sobre una unica ingesta en tiempo real.

const clima = $('Consultar Clima Real (OpenWeatherMap)').first().json;
const arribos = ($('Consultar Vuelos Arribos Real (AviationStack)').first().json.data) || [];
const salidas = ($('Consultar Vuelos Salidas Real (AviationStack)').first().json.data) || [];
const config = $('Configuracion (Editar Aca)').first().json;

// --- Normalizar meteorologia (formato Triage) ---
// Codigos 200-232 de OpenWeatherMap son el grupo "Thunderstorm".
const CODIGOS_TORMENTA_OWM = [200, 201, 202, 210, 211, 212, 221, 230, 231, 232];
const vientoMps = (clima.wind && clima.wind.speed) || 0;
const rafagaMps = (clima.wind && clima.wind.gust) || vientoMps;
const tieneTormenta = Array.isArray(clima.weather) && clima.weather.some((w) => CODIGOS_TORMENTA_OWM.includes(w.id));
const rafagaKt = Math.round(rafagaMps * 1.94384);
const vientoKt = Math.round(vientoMps * 1.94384);

const meteorologia = {
  tipo_alerta: tieneTormenta ? 'Tormenta Electrica Severa' : 'Sin alerta critica',
  rafagas_viento_kt: rafagaKt,
  actividad_electrica: tieneTormenta,
};

// --- Mismo dato, en el formato que espera "Evaluar Riesgo Meteorologico" (el
// nodo original del Protocolo de Cierre de Rampa). AVISO: OpenWeatherMap no
// reporta windshear ni METAR crudo; ninguna API publica y gratuita expone esos
// dos datos, por eso se documentan explicitamente como no disponibles.
const reporte_meteorologico = {
  estacion: config.aeropuerto_iata,
  nombre_estacion: clima.name || config.aeropuerto_iata,
  hora_reporte_utc: new Date((clima.dt || Math.floor(Date.now() / 1000)) * 1000).toISOString(),
  metar_crudo: (Array.isArray(clima.weather) && clima.weather[0]) ? clima.weather[0].description : 'No disponible (fuera de alcance de OpenWeatherMap)',
  viento: {
    direccion_grados: (clima.wind && clima.wind.deg) || 0,
    velocidad_kt: vientoKt,
    rafaga_kt: rafagaKt,
  },
  visibilidad_m: typeof clima.visibility === 'number' ? clima.visibility : 9999,
  fenomenos: Array.isArray(clima.weather) ? clima.weather.map((w) => w.main) : [],
  actividad_electrica: tieneTormenta,
  windshear_reportado: false,
};

// --- Normalizar vuelos en aproximacion (Rama A del Triage) ---
// No se estima combustible remanente: ninguna API publica expone ese dato
// real (es propietario ACARS/OOOI de cada aerolinea), asi que no se inventa
// un numero para tomar decisiones automaticas sobre eso.
const vuelosEnAproximacion = arribos
  .filter((v) => v.flight_status === 'active')
  .map((v) => ({
    id_vuelo: (v.flight && v.flight.iata) || 'DESCONOCIDO',
    aerolinea: (v.airline && v.airline.name) || 'Desconocida',
    tipo_aeronave: (v.aircraft && v.aircraft.iata) || 'No informado',
    estado_operativo: 'en_aproximacion',
    hora_programada_original: (v.arrival && (v.arrival.estimated || v.arrival.scheduled)) || null,
  }));

// --- Normalizar vuelos en tierra (Rama B del Triage) ---
const vuelosEnTierra = salidas
  .filter((v) => v.flight_status === 'scheduled')
  .map((v) => {
    const scheduled = v.departure && v.departure.scheduled;
    const minutosParaSalida = scheduled ? Math.round((new Date(scheduled).getTime() - Date.now()) / 60000) : 999;
    return {
      id_vuelo: (v.flight && v.flight.iata) || 'DESCONOCIDO',
      aerolinea: (v.airline && v.airline.name) || 'Desconocida',
      tipo_aeronave: (v.aircraft && v.aircraft.iata) || 'No informado',
      estado_operativo: minutosParaSalida <= 20 ? 'listo_para_pushback' : 'embarcando',
      hora_programada_original: scheduled || null,
    };
  });

const vuelosActivos = vuelosEnAproximacion.concat(vuelosEnTierra);

// --- Mismo listado, en el formato que espera "Evaluar Riesgo Meteorologico" ---
const vuelos_programados = vuelosActivos.map((v) => ({
  vuelo: v.id_vuelo,
  aerolinea: v.aerolinea,
  aeronave: v.tipo_aeronave,
  matricula: 'No informado',
  tipo_operacion: v.estado_operativo === 'en_aproximacion' ? 'aterrizaje' : 'despegue',
  origen: v.estado_operativo === 'en_aproximacion' ? 'N/D' : config.aeropuerto_iata,
  destino: v.estado_operativo === 'en_aproximacion' ? config.aeropuerto_iata : 'N/D',
  hora_programada_utc: v.hora_programada_original,
  posicion_rampa: 'N/D',
  estado: v.estado_operativo,
}));

// Cachear TODO (los dos formatos) para las ejecuciones (cada 10s) que no
// necesiten volver a golpear las APIs externas.
const data = $getWorkflowStaticData('global');
data.ultimaConsultaApisTimestamp = Date.now();
data.meteorologiaCacheada = meteorologia;
data.vuelosActivosCacheados = vuelosActivos;
data.reporteMeteorologicoCacheado = reporte_meteorologico;
data.vuelosProgramadosCacheados = vuelos_programados;

return [{ json: { meteorologia, vuelos_activos: vuelosActivos, reporte_meteorologico, vuelos_programados } }];

const cache = $json;
return [
  {
    json: {
      meteorologia: cache.meteorologia_cacheada,
      vuelos_activos: cache.vuelos_activos_cacheados,
      reporte_meteorologico: cache.reporte_meteorologico_cacheado,
      vuelos_programados: cache.vuelos_programados_cacheados,
    },
  },
];

const DEMORA_ESTIMADA_MINUTOS = 90;

const vuelo = $json;
const etdOriginal = new Date(vuelo.hora_programada_original);
const nuevoEtd = new Date(etdOriginal.getTime() + DEMORA_ESTIMADA_MINUTOS * 60000);

return [
  {
    json: {
      id_vuelo: vuelo.id_vuelo,
      aerolinea: vuelo.aerolinea,
      estado_operativo: vuelo.estado_operativo,
      hora_programada_original: vuelo.hora_programada_original,
      demora_aplicada_minutos: DEMORA_ESTIMADA_MINUTOS,
      nuevo_ETD_estimado: nuevoEtd.toISOString(),
    },
  },
];

const estacion = ($json.reporte_meteorologico && $json.reporte_meteorologico.estacion) || 'INCIDENTE';
const fecha = new Date().toISOString().slice(0, 10);
const nombreArchivo = `Reporte Riesgos - ${estacion} - ${fecha}.pdf`;

return {
  json: $json,
  binary: {
    data: {
      ...$binary.data,
      fileName: nombreArchivo,
      mimeType: 'application/pdf',
    },
