};

// Llama a Ollama (IA local) UNA vez por incidente, en serie (await en un for),
// para no saturar el unico slot de inferencia del contenedor (VM sin GPU, 2 vCPU).
// Si una llamada falla o tarda demas, ese incidente cae a un valor por defecto
// seguro (pista_cerrada:false) en vez de abortar toda la ejecucion.

const SYSTEM_PROMPT = "Sos un sistema experto en extraccion de datos aeronauticos (NOTAM). Tu unica tarea es leer el texto crudo de un NOTAM y devolver EXCLUSIVAMENTE un objeto JSON valido, sin texto adicional, sin explicaciones, sin markdown, sin backticks.\n\nEsquema exacto de salida (todas las claves son obligatorias):\n{\n  \"aeropuerto_afectado\": string (codigo ICAO de 4 letras, o \"DESCONOCIDO\" si no se puede determinar),\n  \"pista_afectada\": string (ej. \"11/29\", o \"N/D\" si no aplica o no se menciona),\n  \"motivo\": string (resumen breve en espanol del contenido del segmento E) del NOTAM, en pocas palabras, describiendo la causa real: p. ej. \"cierre por tormenta y windshear\", \"niebla, visibilidad bajo minimos\", \"luces de calle de rodaje fuera de servicio por mantenimiento\"),\n  \"pista_cerrada\": boolean (true unicamente si el segmento E) indica cierre total de una pista, ej. contiene \"RWY ... CLSD\"; false si es una restriccion parcial, mantenimiento de taxiway/luces, o no aplica),\n  \"severidad\": \"BAJA\" | \"MEDIA\" | \"ALTA\"\n}\n\nReglas:\n- El codigo ICAO del aeropuerto afectado esta casi siempre en el segmento Q), inmediatamente despues de \"Q)\". Ejemplo: en \"Q)SAEZ/QMRLC/...\" el aeropuerto es SAEZ. Usa ese codigo para \"aeropuerto_afectado\".\n- En \"pista_afectada\" escribi solo el numero de pista (ej \"11/29\"), sin la palabra RWY. Si no hay pista mencionada usa \"N/D\".\n- No inventes datos que no esten en el texto: usa \"DESCONOCIDO\" o \"N/D\" cuando corresponda.\n- Tu respuesta debe empezar con \"{\" y terminar con \"}\". Nada de texto antes o despues.";

const items = $input.all();
const resultados = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  try {
    const respuesta = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://ollama:11434/api/chat',
      body: {
        model: 'qwen2.5:1.5b-instruct-q4_0',
        stream: false,
        format: 'json',
        messages: [
          { role: 'system', content: SYSTEM_PROMPT },
          { role: 'user', content: item.json.notam_crudo },
        ],
      },
      json: true,
      timeout: 60000,
    });
    resultados.push({ json: respuesta, pairedItem: i });
  } catch (error) {
    resultados.push({
      json: {
        message: { role: 'assistant', content: '{}' },
        error: 'Fallo la llamada a Ollama: ' + error.message,
      },
      pairedItem: i,
    });
  }
}

return resultados;

function haversineKm(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const toRad = (deg) => (deg * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

const MARGEN_SEGURIDAD_KM = 50;

// El nodo de IA reemplaza $json por su propia respuesta -- el incidente
// original (con tormenta_activa y vuelos_en_ruta) se recupera referenciando
// el trigger directamente. Se usa `.item` (no `.first()`) para que, con 17
// incidentes pineados, cada ejecucion tome el incidente que le corresponde a
// ESTA rama puntual, no siempre el primero del pinData.
const incidente = $('Ingesta de Reporte (Manual Trigger)').item.json;
const tormenta = incidente.tormenta_activa;
const vuelos = incidente.vuelos_en_ruta || [];

// Respuesta cruda de la IA: la forma exacta puede variar segun la version del
// nodo OpenAI de n8n, se prueban las variantes mas comunes antes de fallar.
const respuestaIA = $json;
const textoIA =
  (respuestaIA.message && respuestaIA.message.content) ||
  respuestaIA.content ||
  respuestaIA.text ||
  '';

let notam = {
  aeropuerto_afectado: 'DESCONOCIDO',
  pista_afectada: 'N/D',
  motivo: 'No se pudo interpretar la respuesta de la IA',
  pista_cerrada: false,
  severidad: 'BAJA',
};

try {
  notam = JSON.parse(textoIA);
} catch (e) {
  // Se deja el valor por defecto (pista_cerrada: false): un NOTAM mal
  // interpretado por la IA no puede, por si solo, forzar un desvio.
}

const vuelosEvaluados = vuelos.map((vuelo) => {
  const distanciaKm = haversineKm(vuelo.latitud, vuelo.longitud, tormenta.latitud, tormenta.longitud);
  const alertaColision = distanciaKm <= tormenta.radio_impacto_km + MARGEN_SEGURIDAD_KM;
  const pistaCerradaEnDestino = notam.pista_cerrada === true && vuelo.destino === notam.aeropuerto_afectado;
  const desvioRequerido = alertaColision || pistaCerradaEnDestino;

  return {
    id_vuelo: vuelo.id_vuelo,
    destino: vuelo.destino,
    altitud_ft: vuelo.altitud_ft,
    distancia_a_tormenta_km: Math.round(distanciaKm),
    radio_impacto_km: tormenta.radio_impacto_km,
    alerta_colision_climatica: alertaColision,
    pista_cerrada_en_destino: pistaCerradaEnDestino,
    notam_aeropuerto_afectado: notam.aeropuerto_afectado,
    notam_motivo: notam.motivo,
    notam_severidad: notam.severidad,
    desvio_requerido: desvioRequerido,
    accion_sugerida: desvioRequerido ? 'Desviar a aeropuerto alterno (Reroute)' : 'Continuar ruta normal',
  };
});

return vuelosEvaluados.map((v) => ({ json: v }));
